azureLogAnalytics.query:
let envOf = (r: string) { case(
    r has "dis-core-tt02", "TT02",
    r has "dis-core-prod", "PROD",
    "unknown") };
let bucket = (n: string) { case(
    n has "/umbraco/", "Content or API miss",
    n has_any ("robots.txt", "sitemap.xml", "favicon.ico", "apple-touch-icon", ".well-known"), "Crawler / browser asset",
    "Scanner probe") };
requests
| where cloud_RoleName == "kinorgeportal" and toint(resultCode) == 404
| summarize Count = count() by bin(timestamp, $__interval), Category = bucket(name)
| order by timestamp asc
